const RANK_API_URL=(()=>{try{return localStorage.getItem("rankApiUrl")||""}catch(e){return""}})()||"";function rankIds(){const hex=n=>{const a=new Uint8Array(n);return crypto.getRandomValues(a),[...a].map(b=>b.toString(16).padStart(2,"0")).join("")};return/^[0-9a-f]{32}$/.test(game.rankId||"")||(game.rankId=hex(16)),/^[0-9a-f]{32}$/.test(game.rankKey||"")||(game.rankKey=hex(16)),{id:game.rankId,key:game.rankKey}}const rankApiOn=()=>!(!RANK_API_URL||!(window.Capacitor&&Capacitor.isNativePlatform&&Capacitor.isNativePlatform())&&"1"!==localStorage.getItem("rankApiTest"));async function rankApi(a,params,body){const q=new URLSearchParams({a:a,...params||{}}),r=await fetch(RANK_API_URL+"?"+q,body?{method:"POST",headers:{"Content-Type":"text/plain"},body:JSON.stringify({...rankIds(),...body})}:{}),j=await r.json();if(!j.ok)throw new Error(j.error||"ranking api");return j}const rankServerApi={kind:"xserver",get uid(){return rankApiOn()?rankIds().id.slice(0,12):null},rankTop:async(f,n)=>(await rankApi("top",{f:f,n:n})).list,dailyTop:async(day,n)=>(await rankApi("dtop",{day:day,n:n})).list,rankPut:d=>rankApi("put",null,d),dailyPut:(day,d)=>rankApi("dput",null,{...d,day:day}),rankAbove:async(f,v,day)=>(await rankApi("above",day?{day:day,v:v}:{f:f,v:v})).count,dailyNear:async(day,c)=>{const j=await rankApi("near",{day:day,c:c});return{up:j.up,down:j.down}},rankCount:async()=>(await rankApi("count")).count};function rankSrv(){return rankApiOn()?rankServerApi:window.fbCloud}